    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <style>
        :root{--paper:#f5f2ec;--white:#fffefa;--ink:#1d2731;--muted:#5e6871;--line:#d9dedf;--blue:#174eb5;--blue-dark:#103a86;--blue-pale:#e7eefb;--orange:#e56c37;--orange-pale:#fff0e7;--green:#405c4c;--serif:Georgia,'Times New Roman',serif;--page:1200px}
        *{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:86px}body{margin:0;background:var(--paper);color:var(--ink);font:400 16px/1.65 var(--font-sans,ui-sans-serif,system-ui,sans-serif)}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button{cursor:pointer}svg{display:block;width:20px;height:20px;flex:none}.bulang-wrap{width:min(var(--page),calc(100% - 48px));margin-inline:auto}.bulang-kicker{display:flex;align-items:center;gap:9px;color:var(--blue);font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}.bulang-kicker::before{width:22px;height:2px;content:"";background:var(--orange)}
