ht:18px}.overlay-budget{display:flex;align-items:baseline;justify-content:space-between;gap:14px;margin:14px 0;padding:14px 16px;border-left:4px solid var(--orange);color:#fff;background:var(--blue-dark)}.overlay-budget span{color:#dce8ff;font-size:14px;font-weight:700}.overlay-budget strong{color:#fff;font-size:clamp(22px,3vw,28px);font-weight:900;line-height:1.1;text-align:right;overflow-wrap:anywhere}.overlay-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.overlay-row{display:grid;gap:3px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}.overlay-row span{color:var(--muted)}.overlay-row strong{color:var(--ink);font-size:15px;font-weight:800;text-align:left;overflow-wrap:anywhere}.overlay-row.is-wide{grid-column:1/-1}.overlay-details{margin:12px 0 0;color:var(--ink);font-size:14px;line-height:1.55;white-space:pre-line;overflow-wrap:anywhere}
