        .profile-layout{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(32px,7vw,80px)}.profile-copy h2{max-width:11ch;margin:10px 0 12px;font-size:clamp(36px,5vw,58px);letter-spacing:-.065em;line-height:.95}.profile-copy p{max-width:43ch;color:var(--muted);font-size:13px}.profile-list{margin:0;border-top:1px solid var(--line)}.profile-row{display:grid;grid-template-columns:1fr auto;gap:14px;padding:13px 2px;border-bottom:1px solid var(--line);font-size:12px}.profile-row dt{color:var(--muted)}.profile-row dd{margin:0;font-weight:800;text-align:right}.profile-row small{display:block;margin-top:2px;color:var(--muted);font-size:9px;font-weight:500}.location-layout{display:grid;grid-template-columns:.72fr 1.28fr;gap:28px;align-items:stretch}.location-copy h2{margin:9px 0 20px;font-size:clamp(32px,4vw,46px);letter-spacing:-.06em;line-height:1}.location-detail{display:grid;gap:12px}.location-detail div{padding-bottom:11px;border-bottom:1px solid var(--line)}.location-detail strong,.location-detail span{display:block}.location-detail strong{font-size:11px}.location-detail span{margin-top:2px;color:var(--muted);font-size:11px}.map-frame{min-height:330px;overflow:hidden;border:1px solid var(--line);background:#e8e9e5}.map-frame iframe{display:block;width:100%;height:100%;min-height:330px;border:0}
        .proposal-fab{position:fixed;right:22px;bottom:20px;z-index:50;display:flex;min-height:52px;align-items:center;gap:10px;padding:0 17px;border:0;color:#fff;background:var(--blue);box-shadow:0 7px 22px rgb(16 58 134 / 27%);font-size:12px;font-weight:850}.proposal-fab svg{width:20px;height:20px}.chat-panel{position:fixed;right:22px;bottom:84px;z-index:51;display:none;width:min(370px,calc(100vw - 28px));max-height:min(560px,calc(100dvh - 105px));overflow:auto;border:1px solid var(--line);background:var(--white);box-shadow:0 18px 50px rgb(20 35 56 / 22%)}.chat-panel.open{display:block;animation:chat-in .18s ease-out}@keyframes chat-in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}.chat-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;color:#fff;background:var(--blue)}.chat-head strong{font-size:13px}.chat-head button{display:grid;width:30px;height:30px;place-items:center;border:1px solid rgb(255 255 255 / 38%);color:#fff;background:transparent}.chat-head svg{width:15px;height:15px}.chat-body{padding:14px}.chat-message{width:fit-content;max-width:92%;margin:0 0 8px;padding:9px 11px;background:#edf1f7;font-size:12px;white-space:pre-line}.chat-prompt{margin:12px 0 7px;color:var(--muted);font-size:10px}.chat-input{width:100%;min-height:40px;padding:9px;border:1px solid var(--line);background:#fff;font-size:12px}.chat-input:focus{outline:2px solid var(--blue);outline-offset:1px}.chat-actions,.chat-options{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}.chat-actions button,.chat-options button{min-height:35px;padding:0 12px;border:1px solid #cbd3df;color:var(--blue);background:#fff;font-size:11px;font-weight:800}.chat-actions button.primary{border-color:var(--blue);color:#fff;background:var(--blue)}.chat-actions button:disabled{opacity:.55;cursor:wait}.chat-error{margin-top:8px;color:#a32929;font-size:11px}.dialog{width:min(420px,calc(100vw - 28px));padding:0;border:1px solid var(--line);background:var(--white)}.dialog::backdrop{background:rgb(15 26 37 / 48%)}.dialog-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;color:#fff;background:var(--blue)}.dialog-head strong{font-size:13px}.dialog-body{padding:17px;font-size:13px}.dialog-body p{margin:0;color:var(--muted)}
        .reveal{opacity:0;transform:translateY(12px);transition:opacity .45s ease,transform .45s ease}.reveal.is-visible{opacity:1;transform:none}
        @media(max-width:900px){.main-nav{gap:12px;font-size:11px}.main-nav a:nth-child(5),.main-nav a:nth-child(6){display:none}.project-list{grid-template-columns:repeat(2,minmax(0,1fr))}.staff-row{grid-template-columns:28px 1fr}.staff-row small{grid-column:2;text-align:left}}
        @media(max-width:700px){.bulang-wrap{width:calc(100% - 32px)}.utility-inner{min-height:30px;font-size:10px}.utility-inner p:last-child{display:none}.header-inner{min-height:66px}.menu-toggle{display:grid}.main-nav{position:absolute;top:calc(100% + 1px);right:0;left:0;display:none;align-items:stretch;gap:0;padding:8px 16px 14px;border-bottom:1px solid var(--line);background:var(--paper);box-shadow:0 12px 18px rgb(20 35 56 / 8%)}.main-nav.open{display:flex;flex-direction:column}.main-nav a{padding:10px 4px}.main-nav .nav-cta{padding:10px 12px}.hero{padding-top:12px}.hero-panel{grid-template-columns:1fr;min-height:0}.hero-main{min-height:365px;padding:32px 25px}.hero h1{font-size:clamp(48px,13vw,72px)}.hero-note{min-height:270px;padding:20px 24px}.notice-paper{max-width:400px;margin:8px auto;width:100%}.hero-meta{margin-top:14px}.ticker-inner{grid-template-columns:1fr auto;gap:8px 12px;padding-block:13px}.ticker-label{grid-column:1/-1}.ticker-text{font-size:11px}.ticker-link{font-size:10px}.section{padding-block:54px}.section-head,.project-head{align-items:flex-start;flex-direction:column;gap:12px;margin-bottom:22px}.section-head h2{font-size:36px}.section-head>p{font-size:12px}.welcome-grid,.service-layout,.profile-layout,.location-layout{grid-template-columns:1fr;gap:25px}.welcome-copy h2{font-size:43px}.staff-panel{padding:20px}.civic-layout{grid-template-columns:1fr}.data-sheet{padding:20px}.project-list{grid-template-columns:1fr}.project-card{min-height:190px}.news-grid{grid-template-columns:1fr}.news-feature{min-height:220px;padding:22px}.news-side{grid-template-columns:1fr}.profile-copy h2{font-size:43px}.location-layout{gap:20px}.map-frame,.map-frame iframe{min-height:270px}.proposal-fab{right:14px;bottom:14px;width:52px;min-height:52px;justify-content:center;padding:0}.proposal-fab .fab-label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.chat-panel{right:12px;bottom:76px;max-height:calc(100dvh - 92px)}.reveal{transform:translateY(8px)}}
        @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.reveal{opacity:1;transform:none;transition:none}.chat-panel.open{animation:none}}
        @media(max-width:700px){.project-overlay{right:16px;width:min(520px,calc(100vw - 32px));padding:14px}.overlay-grid{gap:0 12px}.overlay-budget{gap:10px;padding:12px}.overlay-budget strong{font-size:22px}}
    </style>
