<body>
    <div class="utility"><div class="bulang-wrap utility-inner"><p>Pemerintah Desa Bulang <span aria-hidden="true">·</span> Kecamatan Gending</p><p>Kabupaten Probolinggo, Jawa Timur</p></div></div>
    <header class="site-header"><div class="bulang-wrap header-inner"><a class="brand" href="#beranda" aria-label="Beranda Desa Bulang"><span class="portal-village-logo" aria-hidden="true"><img src="{{ asset('images/portal-logo.webp') }}" alt="" width="44" height="44"></span><span class="brand-copy"><strong>PEMERINTAH DESA BULANG</strong><small>Portal informasi warga</small></span></a><button class="menu-toggle" id="menu-toggle" type="button" aria-label="Buka menu" aria-expanded="false" aria-controls="main-nav"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button><nav class="main-nav" id="main-nav" aria-label="Navigasi utama"><a href="#pemerintahan">Pemerintahan</a><a href="#layanan">Layanan</a><a href="#anggaran">APBDes</a><a href="#proyek">Pembangunan</a><a href="#kabar">Kabar</a><a href="#profil">Profil</a><a class="nav-cta" href="#lokasi">Kunjungi kantor</a></nav></div></header>
    <main>
        <section class="hero" id="beranda"><div class="bulang-wrap hero-panel"><div class="hero-main"><span class="bulang-kicker">Portal informasi Desa Bulang</span><h1>Ruang informasi warga.</h1><p>Akses informasi pemerintahan, layanan, anggaran, dan pembangunan Desa Bulang melalui satu laman.</p><div class="hero-actions"><a class="hero-button primary" href="#layanan">Lihat layanan <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a><a class="hero-button" href="#proyek">Pantau pembangunan</a></div></div><aside class="hero-note"><div class="notice-top"><span>Pusat informasi</span><span class="notice-live">Kanal desa</span></div><article class="notice-paper"><span class="sample-label"></span><small>Pengumuman desa · 18 Mei</small><h2>Jadwal layanan administrasi</h2><p>Pelayanan surat keterangan contoh dibuka pada hari kerja di kantor desa.</p><div class="paper-rule"></div><div class="paper-foot"><span>Desa Bulang</span><span>Informasi</span></div></article><div class="hero-meta"><strong>Desa Bulang</strong>Kecamatan Gending · Kabupaten Probolinggo</div></aside></div></section>
        <div class="ticker"><div class="bulang-wrap ticker-inner"><span class="ticker-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 5h16v14H4zM8 9h8M8 13h5"/></svg>Informasi warga</span><p class="ticker-text"><span class="sample-label">Contoh</span> Posyandu warga · Selasa, 21 Mei · Balai desa</p><a class="ticker-link" href="#kabar">Lihat kabar <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></div></div>
        <section class="section section-white" id="pemerintahan"><div class="bulang-wrap welcome-grid"><div class="welcome-copy"><span class="bulang-kicker">Sambutan kepala desa</span><h2>Selamat datang di Desa Bulang.</h2><p>Selamat datang di portal informasi Desa Bulang. Kami membuka ruang informasi dan komunikasi agar warga lebih mudah mengenal layanan serta perkembangan desa.</p><div class="welcome-person"><span class="person-mark" aria-hidden="true">K</span><span><strong>Nama Kepala Desa Contoh</strong><small>Kepala Desa Bulang</small></span></div></div><div class="staff-panel"><div class="staff-panel-head"><h3>Perangkat desa</h3><small class="sample-label"></small></div><ol class="staff-list"><li class="staff-row"><span>01</span><strong>Nama Sekretaris Contoh</strong><small>Sekretaris Desa</small></li><li class="staff-row"><span>02</span><strong>Nama Kasi Contoh</strong><small>Kasi Pemerintahan</small></li><li class="staff-row"><span>03</span><strong>Nama Kasi Contoh</strong><small>Kasi Kesejahteraan</small></li><li class="staff-row"><span>04</span><strong>Nama Kaur Contoh</strong><small>Kaur Umum</small></li></ol></div></div></section>
        <section class="section" id="layanan"><div class="bulang-wrap service-layout"><div class="service-intro"><span class="bulang-kicker">Administrasi warga</span><span class="sample-label"></span><h2>Urusan desa, lebih jelas.</h2><p>Pilih keperluan untuk melihat informasi layanan yang tersedia.</p></div><div class="service-list"><article class="service-item"><span class="service-number">01</span><details><summary>Surat keterangan <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14m-7-7h14"/></svg></summary><p>KTP dan Kartu Keluarga. Serahkan salinan kepada petugas layanan.</p></details></article><article class="service-item"><span class="service-number">02</span><details><summary>Administrasi kependudukan <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14m-7-7h14"/></svg></summary><p>KTP dan Kartu Keluarga. Serahkan salinan kepada petugas layanan.</p></details></article><article class="service-item"><span class="service-number">03</span><details><summary>Surat pengantar <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14m-7-7h14"/></svg></summary><p>KTP dan Kartu Keluarga. Serahkan salinan kepada petugas layanan.</p></details></article><article class="service-item"><span class="service-number">04</span><details><summary>Layanan lainnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14m-7-7h14"/></svg></summary><p>Konsultasi layanan administrasi langsung di kantor desa.</p></details></article></div></div></section>
        <section class="section section-white" id="anggaran"><div class="bulang-wrap"><div class="section-head"><div><span class="bulang-kicker">Keterbukaan anggaran</span><h2>Anggaran dan indeks desa.</h2></div><p>Ringkasan APBDes dan informasi indeks Desa Bulang.</p></div><div class="civic-layout portal-mobile-stack"><article class="data-sheet"><div class="data-head"><h3>APBDes</h3><label><span class="sr-only">Tahun anggaran</span><select class="year-select" id="budget-year" aria-label="Pilih tahun anggaran" hidden><option value="">Tahun</option></select></label></div><div class="budget-list" id="budget-lines"><span class="sample-label">2025</span><div class="budget-line"><span>Pendapatan</span><strong>Rp 1.245.000.000</strong></div><div class="budget-line"><span>Belanja</span><strong>Rp 1.180.000.000</strong></div><div class="budget-line"><span>Pembiayaan</span><strong>Rp 45.000.000</strong></div></div><div class="budget-total"><span id="budget-realized-label">Realisasi · contoh</span><strong id="budget-realized">Rp 623.500.000</strong></div></article><article class="data-sheet"><div class="data-head"><h3>Indeks Desa</h3><span class="sample-label">2025</span></div><div class="index-caption"><strong>Nilai indeks contoh</strong><span class="index-value">0,71</span></div><div class="index-dims"><div class="index-dim"><span>Layanan dasar</span><strong>0,76</strong><div class="index-track"><i style="width:76%"></i></div></div><div class="index-dim"><span>Sosial</span><strong>0,68</strong><div class="index-track"><i style="width:68%"></i></div></div><div class="index-dim"><span>Ekonomi</span><strong>0,72</strong><div class="index-track"><i style="width:72%"></i></div></div><div class="index-dim"><span>Lingkungan</span><strong>0,69</strong><div class="index-track"><i style="width:69%"></i></div></div></div></article></div></div></section>
        <section class="section" id="proyek"><div class="bulang-wrap"><div class="project-head"><div><span class="bulang-kicker">Pembangunan desa</span><h2>Papan proyek</h2></div><p>Informasi pekerjaan dan kegiatan pembangunan Desa Bulang.</p></div><div class="project-list" id="project-list" aria-live="polite" aria-busy="true">
                    <p class="portal-data-empty" role="status">Memuat informasi pembangunan…</p>
                </div></div></section>
        <section class="section section-blue" id="kabar"><div class="bulang-wrap"><div class="section-head"><div><span class="bulang-kicker">Kabar desa</span><h2>Catatan kegiatan dan pengumuman.</h2></div><p>Informasi terbaru dari Pemerintah Desa Bulang.</p></div><div class="news-grid portal-mobile-stack"><article class="news-feature"><div><small>Pengumuman</small><h3>Jadwal pelayanan keliling</h3><p>Contoh agenda layanan administrasi di balai warga pada pekan terakhir bulan ini.</p></div><div class="feature-foot"><span>Pemerintah Desa Bulang</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17 17 7M8 7h9v9"/></svg></div></article><div class="news-side"><article class="news-row"><small>Agenda warga</small><h3>Pertemuan RT dan RW</h3><p>Rabu, 22 Mei · Pukul 19.00 · Balai desa</p></article><article class="news-row"><small>Kegiatan desa</small><h3>Kerja bakti lingkungan</h3><p>Minggu, 26 Mei · Titik kumpul di balai desa</p></article></div></div></div></section>
        <section class="section section-white" id="profil"><div class="bulang-wrap profile-layout"><div class="profile-copy"><span class="bulang-kicker">Profil desa</span><h2>Mengenal Desa Bulang.</h2><p>Informasi wilayah dan pemerintahan Desa Bulang.</p></div><dl class="profile-list"><div class="profile-row"><dt>Kecamatan</dt><dd>Gending</dd></div><div class="profile-row"><dt>Kabupaten</dt><dd>Probolinggo</dd></div><div class="profile-row"><dt>Provinsi</dt><dd>Jawa Timur</dd></div><div class="profile-row"><dt>Alamat kantor desa</dt><dd>Jl. Desa Bulang No. 01<small></small></dd></div><div class="profile-row"><dt>Luas wilayah</dt><dd>325 ha<small></small></dd></div><div class="profile-row"><dt>Jumlah penduduk</dt><dd>3.240 jiwa<small>2025</small></dd></div></dl></div></section>
        <section class="section" id="lokasi"><div class="bulang-wrap location-layout"><div class="location-copy"><span class="bulang-kicker">Lokasi</span><h2>Kunjungi kantor desa.</h2><div class="location-detail"><div><strong>Alamat</strong><span>Jl. Desa Bulang No. 01 <span class="sample-label">Contoh</span></span></div><div><strong>Telepon</strong><span>08xx-xxxx-xxxx <span class="sample-label">Contoh</span></span></div><div><strong>Jam pelayanan</strong><span>Senin–Jumat, 08.00–14.00 <span class="sample-label">Contoh</span></span></div></div></div><div class="map-frame"><iframe title="Peta Desa Bulang, Kecamatan Gending" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3952.9369735044343!2d113.32409587580293!3d-7.796497992223647!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2dd7ab2c448d39bb%3A0x7a1155ecb6335335!2sKantor%20Desa%20Bulang!5e0!3m2!1sid!2sid!4v1794629008394!5m2!1sid!2sid" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div></div></section>
    </main>
    @include('desa.partials.footer', [
        'villageName' => 'Bulang',
        'initial' => 'B',
        'theme' => 'bulang',
        'links' => [
            ['label' => 'Profil Desa', 'href' => '#profil'],
            ['label' => 'Layanan', 'href' => '#layanan'],
            ['label' => 'APBDes', 'href' => '#anggaran'],
            ['label' => 'Papan proyek', 'href' => '#proyek'],
            ['label' => 'Lokasi kantor', 'href' => '#lokasi'],
        ],
    ])
    <button class="proposal-fab" id="proposal-open" type="button" aria-label="Sampaikan usulan" aria-expanded="false" aria-controls="proposal-chat"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l1.7-3.4A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 11h8M8 14h5"/></svg><span class="fab-label">Sampaikan usulan</span></button>
    <section class="chat-panel" id="proposal-chat" aria-label="Form usulan warga" aria-hidden="true"><div class="chat-head"><strong>Usulan warga</strong><button id="proposal-close" type="button" aria-label="Tutup percakapan"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="chat-body"><div id="chat-messages" aria-live="polite"></div><div id="chat-controls"></div><div class="chat-actions" id="chat-actions"></div><div class="chat-error" id="chat-error" role="alert"></div></div></section>
        <script>
        const safeNode=(tag,className,value)=>{const node=document.createElement(tag);node.className=className;node.textContent=value??'';return node};
        const money=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        if('IntersectionObserver'in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('is-visible',entry.isIntersecting)),{threshold:.1});document.querySelectorAll('main > section').forEach(section=>{section.classList.add('reveal');observer.observe(section)})}
        const nav=document.querySelector('#main-nav'),menuButton=document.querySelector('#menu-toggle');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Tutup menu':'Buka menu')});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));
        const isAmount=value=>/^(?:rp\s*)?[\d.,\s]+$/i.test(String(value??'').trim())&&/\d/.test(String(value??''));
        const projectBudget=project=>[project.summary,project.funding].find(isAmount)||'';
        const projectFundingSource=project=>project.funding&&!isAmount(project.funding)?project.funding:'Belum tersedia';
        const formatProjectBudget=value=>{const text=String(value??'').trim();if(!text)return 'Belum tersedia';if(/^\d+$/.test(text))return money(Number(text));return text};
        function closeProjectOverlay(overlay){
            overlay.classList.remove('open');
            const trigger=document.querySelector(`[aria-controls="${overlay.id}"]`);
            trigger?.setAttribute('aria-expanded','false');
            trigger?.focus();
        }
        document.addEventListener('keydown',event=>{
            if(event.key==='Escape'){
                const overlay=document.querySelector('.project-overlay.open');
                if(overlay)closeProjectOverlay(overlay);
            }
        });
        function renderProjects(projects, emptyMessage='Belum ada informasi pembangunan yang dapat ditampilkan.'){
            const list=document.querySelector('#project-list');
            list.replaceChildren();
            list.setAttribute('aria-busy','false');
            if(!projects.length){const empty=safeNode('p','portal-data-empty',emptyMessage);list.append(empty);return;}
            projects.forEach((project,index)=>{
                const card=document.createElement('article');card.className='project-card';
                const top=document.createElement('div');top.className='project-top';
                top.append(safeNode('span','',`Tahun ${project.year||'—'}`),safeNode('span','project-status',project.status||'Status'));

                const title=safeNode('h3','',project.title);
                const descriptiveSummary=project.summary&&!isAmount(project.summary)?project.summary:'';
                const summary=safeNode('p','',descriptiveSummary||project.location||'Rincian belum tersedia.');
                const bottom=document.createElement('div');bottom.className='project-bottom';
                const budgetSummary=document.createElement('div');budgetSummary.className='project-card-budget';
                budgetSummary.append(safeNode('span','','Anggaran'),safeNode('strong','',formatProjectBudget(projectBudget(project))));
                bottom.append(budgetSummary);
                const detail=safeNode('button','project-detail','Rincian pekerjaan');detail.type='button';detail.setAttribute('aria-expanded','false');
                const overlay=document.createElement('div');overlay.className='project-overlay';overlay.id=`bulang-project-details-${project.id??index}`;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label',`Rincian ${project.title}`);detail.setAttribute('aria-controls',overlay.id);
                const head=document.createElement('div');head.className='overlay-head';head.append(safeNode('strong','','Rincian pekerjaan'));
                const close=document.createElement('button');close.className='overlay-close';close.type='button';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';
                close.addEventListener('click',()=>closeProjectOverlay(overlay));head.append(close);overlay.append(head);
                const budget=document.createElement('div');budget.className='overlay-budget';budget.append(safeNode('span','','Anggaran'),safeNode('strong','',formatProjectBudget(projectBudget(project))));overlay.append(budget);
                const grid=document.createElement('div');grid.className='overlay-grid';
                const addRow=(label,value)=>{const row=document.createElement('div');row.className='overlay-row';row.append(safeNode('span','',label),safeNode('strong','',value||'Belum tersedia'));grid.append(row)};
                addRow('Lokasi',project.location);addRow('Tahun',String(project.year||''));
                addRow('Status',project.status);addRow('Volume',project.volume);
                addRow('Sumber dana',projectFundingSource(project));addRow('Pelaksana',project.executor);
                addRow('Jadwal',project.schedule);addRow('Progres',project.progress==null?'':`${project.progress}%`);
                addRow('Realisasi belanja',money(Number(project.spent)||0));
                overlay.append(grid);
                const details=safeNode('p','overlay-details',project.details||descriptiveSummary||'Rincian pekerjaan belum tersedia.');overlay.append(details);
                bottom.append(detail);card.append(top,title,summary,bottom,overlay);list.append(card);
                detail.addEventListener('click',()=>{
                    const shouldOpen=!overlay.classList.contains('open');
                    document.querySelectorAll('.project-overlay.open').forEach(open=>open.classList.remove('open'));
                    document.querySelectorAll('.project-detail[aria-expanded="true"]').forEach(button=>button.setAttribute('aria-expanded','false'));
                    if(shouldOpen){overlay.classList.add('open');detail.setAttribute('aria-expanded','true')}
                });
            });
        }
        fetch('/api/desa/bulang/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>renderProjects(Array.isArray(data.projects)?data.projects:[])).catch(()=>renderProjects([],'Informasi pembangunan belum dapat dimuat saat ini.'));
        const year=document.querySelector('#budget-year'),budgetLines=document.querySelector('#budget-lines'),realized=document.querySelector('#budget-realized');let budgets=[];function renderBudget(value){const budget=budgets.find(item=>String(item.year)===String(value));if(!budget)return;document.querySelector('#budget-sample')?.remove();document.querySelector('#budget-realized-label').textContent='Realisasi';budgetLines.replaceChildren();[['Pendapatan',budget.revenue],['Belanja',budget.expenditure],['Pembiayaan',budget.financing]].forEach(([label,amount])=>{const row=document.createElement('div');row.className='budget-line';row.append(safeNode('span','',label),safeNode('strong','',money(amount)));budgetLines.append(row)});realized.textContent=money(budget.realized)}year.addEventListener('change',()=>renderBudget(year.value));fetch('/api/desa/bulang/budgets').then(response=>response.ok?response.json():Promise.reject()).then(data=>{budgets=data;if(!budgets.length)return;year.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);year.append(option)});year.value=String(budgets[0].year);renderBudget(year.value)}).catch(()=>{});
        const questions=[{key:'title',label:'Judul usulan',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',label:'Lokasi',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',label:'Bidang',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',label:'Uraian',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',label:'Nama',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',label:'Kontak',prompt:'Nomor telepon (opsional).',required:false,type:'text'}];let answers={},step=0;const chat=document.querySelector('#proposal-chat'),messages=document.querySelector('#chat-messages'),controls=document.querySelector('#chat-controls'),actions=document.querySelector('#chat-actions'),error=document.querySelector('#chat-error'),proposalButton=document.querySelector('#proposal-open');function say(text){messages.append(safeNode('div','chat-message',text));messages.scrollTop=messages.scrollHeight}function action(label,handler,primary=false){const button=safeNode('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function closeChat(clear=true){chat.classList.remove('open');chat.setAttribute('aria-hidden','true');proposalButton.setAttribute('aria-expanded','false');if(clear){answers={};step=0;messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();error.textContent=''}}function renderQuestion(){controls.replaceChildren();actions.replaceChildren();error.textContent='';if(step>=questions.length){say('Periksa kembali usulanmu sebelum dikirim.');say(`${answers.title}
${answers.location}
${answers.description}`);actions.append(action('Batal',()=>closeChat()),action('Kirim usulan',submitProposal,true));return}const question=questions[step];say(question.prompt);controls.append(safeNode('div','chat-prompt',`${step+1} dari ${questions.length} · ${question.label}`));if(question.type==='choice'){const options=document.createElement('div');options.className='chat-options';question.options.forEach(option=>options.append(action(option,()=>{answers[question.key]=option;say(option);step++;renderQuestion()})));controls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='chat-input';input.placeholder=question.label;input.setAttribute('aria-label',question.label);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;controls.append(input)}actions.append(action('Batal',()=>closeChat()));if(!question.required)actions.append(action('Lewati',()=>{answers[question.key]='';step++;renderQuestion()}));actions.append(action(step===questions.length-1?'Tinjau':'Lanjut',()=>{const input=controls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){error.textContent='Bagian ini perlu diisi.';return}answers[question.key]=value;if(value)say(value);step++;renderQuestion()},true))}async function submitProposal(){error.textContent='';const submitButton=actions.querySelector('.primary');submitButton.disabled=true;try{const response=await fetch('/api/desa/bulang/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({...answers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();say(result.message||'Usulan berhasil dikirim.');actions.append(action('Selesai',()=>closeChat(),true))}catch(exception){error.textContent=exception.message;submitButton.disabled=false}}proposalButton.addEventListener('click',()=>{chat.classList.add('open');chat.setAttribute('aria-hidden','false');proposalButton.setAttribute('aria-expanded','true');if(!messages.childElementCount)renderQuestion()});document.querySelector('#proposal-close').addEventListener('click',()=>closeChat(false));
    </script>
    @include('desa.partials.responsive')
</body>
</html>
